      content: "";
      position: absolute;
      inset: 0;
      background:
        radial-gradient(circle at 15% 15%, rgba(110, 168, 255, 0.2), transparent 22%),
        radial-gradient(circle at 85% 15%, rgba(255, 93, 115, 0.14), transparent 18%);
      pointer-events: none;
    }

    .topbar {
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding: 22px 28px;
      border-bottom: 1px solid var(--border);
      backdrop-filter: blur(18px);
      background: rgba(10, 13, 20, 0.55);
      position: relative;
      z-index: 1;
    }

    .brand {
      font-size: 0.94rem;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: var(--muted);
    }

    .status-chip {
      padding: 8px 12px;
      border-radius: 999px;
      border: 1px solid rgba(110, 168, 255, 0.25);
      background: rgba(110, 168, 255, 0.08);
      color: #cfe0ff;
      font-size: 0.86rem;
    }

    .page {
      position: relative;
      z-index: 1;
      display: grid;
      grid-template-columns: 1.2fr 0.8fr;
      gap: 28px;
      padding: 32px;
    }

    .preview-card,
    .meta-card {
      border: 1px solid var(--border);
      border-radius: var(--radius);
      background: var(--panel);
      backdrop-filter: blur(18px);
    }

    .preview-card {
      padding: 22px;
    }

    .image-frame {
      margin: 0;
      border-radius: 20px;
      overflow: hidden;
      border: 1px solid rgba(255, 255, 255, 0.08);
      background: #0d1220;
      position: relative;
    }

    .image-frame img {
      display: block;
      width: 100%;
      aspect-ratio: 4 / 3;
      object-fit: cover;
    }

    .image-caption {
      display: flex;
      justify-content: space-between;
      gap: 16px;
      padding: 18px 6px 6px;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .image-caption strong {
      display: block;
      color: var(--text);
      font-size: 1.05rem;
      margin-bottom: 4px;
    }

    .actions {
      display: flex;
      justify-content: flex-end;
      padding-top: 20px;
    }

    .button {
      border: 0;
      border-radius: 14px;
      padding: 13px 18px;
      transition: transform 160ms ease, background 160ms ease, opacity 160ms ease;
    }

    .button:hover {
      transform: translateY(-1px);
    }

    .button:active {
      transform: translateY(0);
    }

    .button-secondary {
      background: rgba(255, 255, 255, 0.06);
      color: var(--text);
    }

    .button-danger {
      background: linear-gradient(180deg, var(--danger), var(--danger-strong));
      color: white;
      box-shadow: 0 14px 32px rgba(255, 63, 90, 0.28);
    }

    .trigger {
      min-width: 148px;
    }

    .meta-card {
      padding: 28px;
      display: flex;
      flex-direction: column;
      gap: 22px;
    }

    .eyebrow {
      color: var(--accent);
      letter-spacing: 0.12em;
      text-transform: uppercase;
      font-size: 0.82rem;
    }

    .meta-card h1 {
      margin: 0;
      font-size: clamp(2rem, 4vw, 3rem);
      line-height: 1;
    }

    .meta-card p {
      margin: 0;
      color: var(--muted);
      line-height: 1.6;
    }

    .detail-grid {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 14px;
    }

    .detail {
      padding: 16px;
      border-radius: 18px;
      background: var(--panel-soft);
      border: 1px solid rgba(255, 255, 255, 0.06);
    }

    .detail span {
      display: block;
      color: var(--muted);
      font-size: 0.84rem;
      margin-bottom: 6px;
    }

    .detail strong {
      font-size: 1.02rem;
    }

    .library-state {
      padding: 18px;
      border-radius: 18px;
      border: 1px solid rgba(255, 255, 255, 0.08);
      background: rgba(255, 255, 255, 0.03);
      color: var(--muted);
    }

    .library-state strong {
      color: var(--text);
      display: block;
      margin-bottom: 6px;
    }

    .overlay {
      position: fixed;
      inset: 0;
      display: grid;
      place-items: center;
      padding: 24px;
      background: rgba(3, 5, 10, 0.72);
      backdrop-filter: blur(12px);
      opacity: 0;
      visibility: hidden;
      transition: opacity 180ms ease, visibility 180ms ease;
    }

    .overlay.open {
      opacity: 1;
      visibility: visible;
    }

    .dialog {
      width: min(100%, 460px);
      border-radius: 28px;
      border: 1px solid rgba(255, 255, 255, 0.1);
      background: linear-gradient(180deg, rgba(23, 29, 43, 0.98), rgba(13, 17, 27, 0.98));
      box-shadow: var(--shadow);
      padding: 28px;
      transform: translateY(10px) scale(0.98);
      transition: transform 180ms ease;
    }

    .overlay.open .dialog {
      transform: translateY(0) scale(1);
    }

    .dialog-icon {
      width: 52px;
      height: 52px;
      border-radius: 16px;
      display: grid;
      place-items: center;
      font-size: 1.3rem;
      background: rgba(255, 93, 115, 0.12);
      color: #ff9dac;
      border: 1px solid rgba(255, 93, 115, 0.18);
      margin-bottom: 18px;
    }

    .dialog h2 {
      margin: 0 0 10px;
      font-size: 1.5rem;
    }

    .dialog p {
      margin: 0;
      color: var(--muted);
      line-height: 1.6;
    }

    .dialog-actions {
      display: flex;
      justify-content: flex-end;
      gap: 12px;
      margin-top: 24px;
    }

    @media (max-width: 860px) {
      .page {
        grid-template-columns: 1fr;
      }
    }

    @media (max-width: 640px) {
      body {
        padding: 16px;
      }

      .shell {
        min-height: auto;
      }

      .topbar,
      .page {
        padding: 20px;
      }

      .detail-grid {
        grid-template-columns: 1fr;
      }

      .dialog-actions {
        flex-direction: column-reverse;
      }

      .dialog-actions .button {
        width: 100%;
      }
    }
  </style>
</head>
<body>
  <div id="root"></div>

  <script>
    const state = {
      isDialogOpen: false,
      isDeleted: false
    };

    const imageSource =
      "data:image/svg+xml;utf8," +
      encodeURIComponent(`
        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1600 1200">
          <defs>
            <linearGradient id="sky" x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stop-color="#253355"/>
              <stop offset="100%" stop-color="#0f1629"/>
            </linearGradient>
            <linearGradient id="sand" x1="0" y1="0" x2="1" y2="1">
              <stop offset="0%" stop-color="#d57a65"/>
              <stop offset="100%" stop-color="#6a3d58"/>
            </linearGradient>
          </defs>
          <rect width="1600" height="1200" fill="url(#sky)"/>
          <circle cx="1180" cy="230" r="88" fill="#f6c88b" opacity="0.92"/>
          <path d="M0 760 C200 640 350 620 500 700 C690 800 840 820 1020 700 C1190 585 1390 620 1600 790 L1600 1200 L0 1200 Z" fill="url(#sand)"/>
          <path d="M0 910 C210 800 390 790 580 900 C770 1010 990 1010 1210 900 C1360 825 1495 820 1600 860 L1600 1200 L0 1200 Z" fill="#1a2238" opacity="0.45"/>
          <path d="M470 700 L640 390 L820 700 Z" fill="#111a2d"/>
          <path d="M700 720 L980 260 L1240 720 Z" fill="#18213a"/>
          <path d="M765 720 L980 360 L1180 720 Z" fill="#243150"/>
        </svg>
      `);

    const Button = ({ label, variant, classes = "", action, type = "button" }) => `
      <button
        type="${type}"
        class="button ${variant} ${classes}".trim()
        data-action="${action}"
      >
        ${label}
      </button>
    `;

    const ConfirmDeleteDialog = () => `
      <div
        class="overlay ${state.isDialogOpen ? "open" : ""}"
        ${state.isDialogOpen ? "" : "hidden"}
        aria-hidden="${state.isDialogOpen ? "false" : "true"}"
      >
        <div
          class="dialog"
          role="dialog"
          aria-modal="true"
          aria-labelledby="dialog-title"
          aria-describedby="dialog-description"
        >
          <div class="dialog-icon" aria-hidden="true">!</div>
          <h2 id="dialog-title">Delete this image?</h2>
          <p id="dialog-description">
            This will permanently remove the image from your library. You can’t undo this action after confirming.
          </p>
          <div class="dialog-actions">
            ${Button({
              label: "Cancel",
              variant: "button-secondary",
              action: "close-dialog"
            })}
            ${Button({
              label: "Delete image",
              variant: "button-danger",
              action: "confirm-delete"
            })}
          </div>
        </div>
      </div>
    `;

    const ImagePreviewPage = () => `
      <main class="shell">
        <header class="topbar">
          <div class="brand">Library / Image Preview</div>
          <div class="status-chip">${state.isDeleted ? "Removed from library" : "Ready to manage"}</div>
        </header>

        <section class="page">
          <article class="preview-card">
            <figure class="image-frame">
              <img
                src="${imageSource}"
                alt="Desert mountain landscape artwork preview"
              />
            </figure>
            <figcaption class="image-caption">
              <div>
                <strong>Evening Dunes</strong>
                <span>${state.isDeleted ? "This image has been deleted from your library." : "Full-resolution preview with dark mode controls."}</span>
              </div>
              <span>4096 x 3072</span>
            </figcaption>
            <div class="actions">
              ${Button({
                label: state.isDeleted ? "Deleted" : "Delete image",
                variant: "button-danger",
                classes: "trigger",
                action: "open-dialog"
              })}
            </div>
          </article>

          <aside class="meta-card">
            <div class="eyebrow">Curated artwork</div>
            <h1>Preview before cleanup.</h1>
            <p>
              Review the image details, then remove it from your library only if you’re sure you no longer need it.
            </p>

            <div class="detail-grid">
              <div class="detail">
                <span>Collection</span>
                <strong>Editorial Selects</strong>
              </div>
              <div class="detail">
                <span>Captured</span>
                <strong>May 2026</strong>
              </div>
              <div class="detail">
                <span>Color profile</span>
                <strong>Display P3</strong>
              </div>
              <div class="detail">
                <span>Visibility</span>
                <strong>Private library</strong>
              </div>
            </div>

            <div class="library-state" aria-live="polite">
              <strong>${state.isDeleted ? "Image deleted" : "Deletion requires confirmation"}</strong>
              ${state.isDeleted
                ? "The preview remains here as a visual placeholder, but the item is marked removed from your library."
                : "Use the delete control below the image to open a confirmation dialog before removing this item."}
            </div>
          </aside>
        </section>
      </main>
      ${ConfirmDeleteDialog()}
    `;

    const App = () => ImagePreviewPage();

    function render() {
      document.getElementById("root").innerHTML = App();
    }

    document.addEventListener("click", (event) => {
      const action = event.target.closest("[data-action]")?.dataset.action;
      if (!action) return;

      if (action === "open-dialog" && !state.isDeleted) {
        state.isDialogOpen = true;
      }

      if (action === "close-dialog") {
        state.isDialogOpen = false;
      }

      if (action === "confirm-delete") {
        state.isDeleted = true;
        state.isDialogOpen = false;
      }

      render();
    });

    document.addEventListener("keydown", (event) => {
      if (event.key === "Escape" && state.isDialogOpen) {
        state.isDialogOpen = false;
        render();
      }
    });

    render();
  </script>
</body>
</html>
