    }

    .shell {
      width: min(100%, 980px);
      min-height: 640px;
      border: 1px solid var(--border);
      border-radius: 32px;
      background: linear-gradient(180deg, rgba(20, 25, 38, 0.98), rgba(10, 13, 20, 0.98));
